export async function startGroupVoice(
  group: string,
  self: string,
  owner: string,
  members: string[],
) {
  const invite = {
    group,
    host: self,
    meeting: crypto.randomUUID(),
    expires: 0,
  };
  const room = await openRoom(invite, self, owner);
  if (!room || session !== room) return;
  useGroupVoice.setState({ active: { group, host: true, joining: false } });
