async fn group_voice_member_requires_the_exact_accepted_device() {
    let root = tempfile::tempdir().unwrap();
    let (node, _) = super::tests::node(&root.path().join("alice"));
    let (invitee, _) = super::tests::node(&root.path().join("bob"));
